   const x=r.preparationStats;assert.deepEqual(Object.keys(x).sort(),['decodeRequests','decodeComputations','decodeHits','satPairCalls','basisRequests','basisComputations','basisHits','peakBodyEntries','peakBasisEntries'].sort());
