 const totals={};if(!firstFailure){for(const r of calls){const key='parent:'+r.name,t=totals[key]??={calls:0,wallNs:'0'};t.calls++;t.wallNs=String(BigInt(t.wallNs)+BigInt(r.parentWallNs??r.parentAskWallNs));}for(const r of timing){const key='reference:'+r.role+':'+r.kind+':'+r.name,t=totals[key]??={calls:0,wallNs:'0',selfReportedHandlerCpuNs:'0'};t.calls++;t.wallNs=String(BigInt(t.wallNs)+BigInt(r.handlerWallNs));t.selfReportedHandlerCpuNs=String(BigInt(t.selfReportedHandlerCpuNs)+BigInt(r.selfReportedHandlerCpuNs));}}
 json(join(out,'result.json'),{status:firstFailure?'PREPARED_OBSERVATIONAL_CENSUS_STOPPED':'PREPARED_OBSERVATIONAL_CENSUS_PHYSICAL_PARITY_CONFIRMED',firstFailure,reports,calls,referenceTiming:timing,preparationTotals,operationTotals:totals,cleanup,timingInterpretable:firstFailure===null,wholeParentWallNs:String(process.hrtime.bigint()-started),parentSelfCpuUs:process.cpuUsage(cpu),cpuBoundary:'Reference CPU is self-reported per handler only; initialization/serialization/finalization excluded. No authoritative complete-owned CPU or resource GO.',API:false,full1200:false,fullP4Qualification:false,resourceQualification:false,independentlyFullAccepted:0});clearTimeout(timer);process.exitCode=firstFailure?1:0;
